// Package postgres implements collab.UpdateLog against PostgreSQL via
// jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/cowork/internal/collab"
	"github.com/garamsh/garam/cowork/internal/collab/postgres/db"
	"github.com/garamsh/garam/platform/sdk/errorx"
)

// foreignKeyViolation is the SQL state of an update for a page that no
// longer exists.
const foreignKeyViolation = "23503"

// ErrPageGone is an update for a page deleted while a client edited it.
var ErrPageGone = errorx.New(errorx.KindNotFound, "collab: the page no longer exists")

// Log implements collab.UpdateLog against PostgreSQL.
type Log struct {
	pool *pgxpool.Pool
}

var _ collab.UpdateLog = (*Log)(nil)

// New answers a log over pool.
func New(pool *pgxpool.Pool) *Log {
	return &Log{pool: pool}
}

func translate(err error, op string) error {
	var pgErr *pgconn.PgError
	switch {
	case err == nil:
		return nil
	case errors.As(err, &pgErr) && pgErr.Code == foreignKeyViolation:
		return ErrPageGone
	}
	return errorx.Wrap(err, "page content: "+op, errorx.KindUnavailable)
}

// Load implements collab.UpdateLog. The snapshot and the updates after
// it are read in one repeatable-read transaction, so a compaction that
// commits between the two reads is seen by neither.
func (l *Log) Load(ctx context.Context, org, page string) (collab.Document, error) {
	var doc collab.Document
	err := pgx.BeginTxFunc(ctx, l.pool, pgx.TxOptions{IsoLevel: pgx.RepeatableRead, AccessMode: pgx.ReadOnly}, func(tx pgx.Tx) error {
		q := db.New(tx)
		snap, err := q.GetSnapshot(ctx, db.GetSnapshotParams{Org: org, PageID: page})
		switch {
		case errors.Is(err, pgx.ErrNoRows):
		case err != nil:
			return err
		default:
			doc.Snapshot, doc.Through = snap.Snapshot, snap.Through
		}
		rows, err := q.ListUpdatesAfter(ctx, db.ListUpdatesAfterParams{Org: org, PageID: page, Seq: doc.Through})
		if err != nil {
			return err
		}
		for _, r := range rows {
			doc.Updates = append(doc.Updates, r.Body)
			doc.Through = r.Seq
		}
		return nil
	})
	return doc, translate(err, "load")
}

// Append implements collab.UpdateLog.
func (l *Log) Append(ctx context.Context, org, page string, update []byte) (int, error) {
	var n int64
	err := pgx.BeginFunc(ctx, l.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		if err := q.AppendUpdate(ctx, db.AppendUpdateParams{Org: org, PageID: page, Body: update}); err != nil {
			return err
		}
		var err error
		n, err = q.CountUpdatesAfterSnapshot(ctx, db.CountUpdatesAfterSnapshotParams{Org: org, PageID: page})
		return err
	})
	return int(n), translate(err, "append")
}

// Compact implements collab.UpdateLog. The updates are dropped only
// where the snapshot was replaced, so an earlier compaction finishing
// last drops nothing a later snapshot does not hold.
func (l *Log) Compact(ctx context.Context, org, page string, merged []byte, through int64) error {
	err := pgx.BeginFunc(ctx, l.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		replaced, err := q.UpsertSnapshot(ctx, db.UpsertSnapshotParams{Org: org, PageID: page, Snapshot: merged, Through: through})
		if err != nil || replaced == 0 {
			return err
		}
		return q.DeleteUpdatesThrough(ctx, db.DeleteUpdatesThroughParams{Org: org, PageID: page, Seq: through})
	})
	return translate(err, "compact")
}
